class Solution {
  public int[] decrypt(int[] code, int k) {
    int n = code.length;
    int[] result = new int[n];
    if (k == 0) return result;
    // window of |k| elements starting right after i (k > 0) or ending right before i (k < 0)
    int start = k > 0 ? 1 : n + k, end = k > 0 ? k : n - 1;
    int window = 0;
    for (int i = start; i <= end; i++) window += code[i % n];
    for (int i = 0; i < n; i++) {
      result[i] = window;
      window -= code[start % n];
      window += code[(end + 1) % n];
      start++;
      end++;
    }
    return result;
  }
}
